import java.io.*;
import java.net.*;
import java.util.*;
import org.minima.objects.base.MiniData;
import org.minima.system.network.p2p.messages.*;
import org.minima.utils.json.*;
import org.minima.utils.json.parser.JSONParser;
public class PeerMessagesOracle {
    static int num(JSONObject obj,String key){return ((Number)obj.get(key)).intValue();}
    static InetSocketAddress address(Object value){if(value==null)return null;var s=(JSONObject)value;return Boolean.TRUE.equals(s.get("unresolved"))?InetSocketAddress.createUnresolved((String)s.get("host"),num(s,"port")):new InetSocketAddress((String)s.get("host"),num(s,"port"));}
    static Object snapshot(InetSocketAddress address){if(address==null)return null;var result=new JSONObject();result.put("host",address.getHostString());result.put("address",address.isUnresolved()?null:address.getAddress().getHostAddress());result.put("port",address.getPort());result.put("text",address.toString());result.put("hash",address.hashCode());return result;}
    static List<InetSocketAddress> list(Object value){if(value==null)return null;var result=new ArrayList<InetSocketAddress>();for(Object item:(JSONArray)value)result.add(address(item));return result;}
    static Object snapshots(List<InetSocketAddress> values){if(values==null)return null;var result=new JSONArray();for(var value:values)result.add(snapshot(value));return result;}
    static Object run(JSONObject request){String kind=(String)request.get("kind");
        if(kind.equals("address")){var a=address(request.get("address"));var result=new JSONObject();result.put("value",snapshot(a));if(request.containsKey("other"))result.put("equal",a.equals(address(request.get("other"))));return result;}
        if(kind.equals("int"))return InetSocketAddressIO.safeReadInt((JSONObject)request.get("object"),"value");
        if(kind.equals("io")){var values=(JSONArray)request.get("value");var peers=((String)request.get("mode")).equals("strings")?InetSocketAddressIO.addressesJSONArrayToList(values):InetSocketAddressIO.addressesJSONToList(values);var result=new JSONObject();result.put("peers",snapshots(peers));try{result.put("objects",InetSocketAddressIO.addressesListToJSON(peers));}catch(Exception e){result.put("objects","ERROR");}try{result.put("strings",InetSocketAddressIO.addressesListToJSONArray(peers));}catch(Exception e){result.put("strings","ERROR");}return result;}
        if(kind.equals("swap")){P2PDoSwap swap=request.containsKey("target")?new P2PDoSwap(new MiniData("0x0001"),address(request.get("target")),(String)request.get("uid")):new P2PDoSwap();boolean random=swap.getSecret().getLength()==(request.containsKey("target")?2:8);swap.setSecret(new MiniData("0x0001"));var out=new JSONArray();for(Object value:(JSONArray)request.get("ops")){var op=(JSONObject)value;Object outcome="OK";try{switch((String)op.get("op")){case "read":swap.readJson((JSONObject)op.get("value"));break;case "target":swap.setSwapTarget(address(op.get("value")));break;case "uid":swap.setSwappingClientUID((String)op.get("value"));break;case "secret":swap.setSecret(op.get("value")==null?null:new MiniData((String)op.get("value")));break;case "new":swap=P2PDoSwap.readFromJson((JSONObject)op.get("value"));break;default:throw new IllegalArgumentException();}}catch(Exception e){outcome="ERROR";}var state=new JSONObject();state.put("result",outcome);state.put("secret",swap.getSecret()==null?null:swap.getSecret().to0xString());state.put("target",snapshot(swap.getSwapTarget()));state.put("uid",swap.getSwappingClientUID());try{state.put("json",swap.toJson());}catch(Exception e){state.put("json","ERROR");}out.add(state);}var result=new JSONObject();result.put("random",random);result.put("states",out);return result;}
        if(kind.equals("walk")){var external=list(request.get("path"));String ctor=(String)request.get("ctor");P2PWalkLinks walk=ctor.equals("path")?new P2PWalkLinks(true,true,external):ctor.equals("target")?new P2PWalkLinks(true,true,"uid"):new P2PWalkLinks();boolean random=walk.getSecret().getLength()==8;walk.setSecret(new MiniData("0x0001"));var out=new JSONArray();for(Object value:(JSONArray)request.get("ops")){var op=(JSONObject)value;Object outcome="OK";try{switch((String)op.get("op")){case "read":walk.fromJson((JSONObject)op.get("value"));break;case "new":walk=P2PWalkLinks.readFromJSON((JSONObject)op.get("value"));break;case "target":walk.setTargetUidForNextHop((String)op.get("value"));break;case "secret":walk.setSecret(op.get("value")==null?null:new MiniData((String)op.get("value")));break;case "path":walk.setPathTaken(list(op.get("value")));break;case "external":external.add(address(op.get("value")));break;case "append":walk.getPathTaken().add(address(op.get("value")));break;case "hop":walk.addHopToPath(address(op.get("value")));break;case "previous":outcome=snapshot(walk.getPreviousNode(address(op.get("value"))));break;default:throw new IllegalArgumentException();}}catch(Exception e){outcome="ERROR";}var state=new JSONObject();state.put("result",outcome);state.put("secret",walk.getSecret()==null?null:walk.getSecret().to0xString());state.put("target",walk.getTargetUidForNextHop());state.put("path",snapshots(walk.getPathTaken()));state.put("walk",walk.isWalkInLinks());state.put("join",walk.isJoiningWalk());state.put("client",walk.isClientWalk());state.put("return",walk.isReturning());state.put("slots",walk.getAvailableNoneP2PConnectionSlots());try{state.put("json",walk.toJson());}catch(Exception e){state.put("json","ERROR");}out.add(state);}var result=new JSONObject();result.put("random",random);result.put("states",out);return result;}
        throw new IllegalArgumentException(kind);
    }
    public static void main(String[] args)throws Exception{var input=new BufferedReader(new InputStreamReader(System.in));String line;while((line=input.readLine())!=null)try{System.out.println(JSONValue.toJSONString(run((JSONObject)new JSONParser().parse(line))));}catch(Exception e){System.out.println("\"ERROR\"");}}
}
